def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(9)]

    lower = [(r, c) for r in range(6, h) for c in range(w) if grid[r][c] == 1]
    if not lower:
        return out

    lr0, lr1 = min(r for r, c in lower), max(r for r, c in lower)
    lc0, lc1 = min(c for r, c in lower), max(c for r, c in lower)
    for r, c in lower:
        rr = r - 6
        if 0 <= rr < 9:
            out[rr][c] = 1

    colors = {grid[r][c] for r in range(5) for c in range(w)} - {0, 1, 2, 5}
    if colors:
        color = next(iter(colors))
        shape = [(r, c) for r in range(5) for c in range(w) if grid[r][c] == color]
        sr0, sr1 = min(r for r, c in shape), max(r for r, c in shape)
        sc0, sc1 = min(c for r, c in shape), max(c for r, c in shape)
        yshift = (lr0 - 6) - 1 - sr1
        xshift = (lc0 + lc1 - sc0 - sc1) // 2
        for r, c in shape:
            rr, cc = r + yshift, c + xshift
            if 0 <= rr < 9 and 0 <= cc < w:
                out[rr][cc] = color

    return out
